 const [dbLoading,setDbLoading]=useState(true);
 useEffect(()=>{localStorage.setItem('isis-health-data',JSON.stringify(data))},[data]);
 const refreshFromDb=async()=>{try{setDbLoading(true);const remote=await apiJson('/insurance/state');setData(remote as StateData);setDbConnected(true);return true}catch(e){setDbConnected(false);notify(`MySQL connection unavailable: ${e instanceof Error?e.message:'check API settings'}`,true);return false}finally{setDbLoading(false)}};
 useEffect(()=>{refreshFromDb()},[]);
