 const ownedPolicyIds=customer?data.policies.filter(p=>p.customerId===customer.id).map(p=>p.id):[];
 const visibleData=useMemo(()=>customer?{...data,customers:[customer],policies:data.policies.filter(x=>x.customerId===customer.id),dependents:data.dependents.filter(x=>ownedPolicyIds.includes(x.policyId)),payments:data.payments.filter(x=>ownedPolicyIds.includes(x.policyId)),claims:data.claims.filter(x=>x.customerId===customer.id),settlements:data.settlements.filter(s=>data.claims.some(c=>c.id===s.claimId&&c.customerId===customer.id)),appeals:data.appeals.filter(a=>data.claims.some(c=>c.id===a.claimId&&c.customerId===customer.id))}:data,[data,customer,ownedPolicyIds]);
 const notify=(text:string,error=false)=>setToast({text,error});
 const persist=(key:keyof StateData,items:any[])=>setData(prev=>({...prev,[key]:items}));
