 const hospitalName=(hid:string)=>data.hospitals.find(h=>h.id===hid)?.name??'Unknown hospital';
 const policyName=(pid:string)=>`${pid} · ${planName(data.policies.find(p=>p.id===pid)?.planId||'')}`;
 const claimById=(cid:string)=>data.claims.find(c=>c.id===cid);
 const open=(kind:string,title:string,record?:any)=>setModal({kind,title,record});
 const submit=async(e:React.FormEvent<HTMLFormElement>)=>{
  e.preventDefault();const form=new FormData(e.currentTarget);const v=(name:string)=>String(form.get(name)||'').trim();
  const required=Array.from(e.currentTarget.querySelectorAll('[required]')) as HTMLInputElement[];
  if(required.some(el=>!el.value.trim())){notify('Complete all required fields before saving',true);return}
  const m=modal;if(!m)return;
  if(m.kind==='customer'){const row={fullName:v('fullName'),dob:v('dob'),gender:v('gender'),phone:v('phone'),email:v('email'),address:v('address')};await apiJson('/insurance/customers',{method:'POST',body:JSON.stringify(row)});await refreshFromDb()}
  if(m.kind==='plan'){const row:Plan={id:id('PLN'),name:v('name'),coveredTreatments:v('coveredTreatments'),coveragePercent:Number(v('coveragePercent')),maxCoverageINR:Number(v('maxCoverageINR')),annualPremiumINR:Number(v('annualPremiumINR'))};persist('plans',[row,...data.plans])}
  if(m.kind==='policy'){const pl=data.plans.find(x=>x.id===v('planId'));const row:Policy={id:id('POL'),customerId:v('customerId'),planId:v('planId'),startDate:v('startDate'),endDate:v('endDate'),sumInsuredINR:Number(v('sumInsuredINR'))||pl?.maxCoverageINR||0,remainingLimitINR:Number(v('sumInsuredINR'))||pl?.maxCoverageINR||0,status:'Active'};persist('policies',[row,...data.policies])}
  if(m.kind==='dependent'){persist('dependents',[{id:id('DEP'),policyId:v('policyId'),name:v('name'),relationship:v('relationship'),dob:v('dob'),gender:v('gender')},...data.dependents])}
  if(m.kind==='payment'){const pay=data.payments.find(p=>p.id===m.record?.id);if(pay)persist('payments',data.payments.map(p=>p.id===pay.id?{...p,status:'Paid',paidDate:v('paidDate'),reference:v('reference')}:p))}
  if(m.kind==='hospital'){await apiJson('/insurance/hospitals',{method:'POST',body:JSON.stringify({name:v('name'),address:v('address'),city:v('city'),phone:v('phone'),category:v('category')})});await refreshFromDb()}
   if(m.kind==='claim'){const uploaded=form.get('documentFile');const documentName=uploaded instanceof File&&uploaded.name?uploaded.name:v('documentName');if(!documentName){notify('Add a document filename or choose a file from this device.',true);return}const created=await apiJson('/insurance/claims',{method:'POST',body:JSON.stringify({customerId:v('customerId'),policyId:v('policyId'),hospitalId:v('hospitalId'),treatment:v('treatment'),claimDate:v('claimDate'),amountINR:Number(v('amountINR')),documentName,documentType:v('documentType')})});await refreshFromDb();setSelectedClaim(created.id)}
  if(m.kind==='settlement'){const claim=claimById(v('claimId'));const amount=Number(v('amountINR'));persist('settlements',[{id:id('SET'),claimId:v('claimId'),date:v('date'),amountINR:amount,status:v('status'),paymentReference:v('paymentReference')},...data.settlements]);if(claim)persist('claims',data.claims.map(c=>c.id===claim.id?{...c,status:'Approved'}:c))}
  if(m.kind==='appeal'){persist('appeals',[{id:id('APL'),claimId:v('claimId'),reason:v('reason'),status:'Submitted',resolutionNotes:''},...data.appeals])}
  setModal(null);notify(`${m.title.replace('Add ','').replace('Record ','')} saved successfully`);
 };
 const removeClaim=async(claim:Claim)=>{if(window.confirm(`Delete claim ${claim.claimNumber}? This action cannot be undone.`)){try{await apiJson(`/insurance/claims/${claim.id}`,{method:'DELETE'});await refreshFromDb();notify('Claim deleted from MySQL')}catch(e){notify(e instanceof Error?e.message:'Could not delete claim',true)}}};
 const updateStatus=(claimId:string,status:string)=>{persist('claims',data.claims.map(c=>c.id===claimId?{...c,status}:c));notify(`Claim marked ${status.toLowerCase()}`)};
 const updateDoc=(claimId:string,docId:string,status:string)=>{persist('claims',data.claims.map(c=>c.id===claimId?{...c,documents:c.documents.map(d=>d.id===docId?{...d,status}:d)}:c));notify(`Document marked ${status.toLowerCase()}`)};
 const runEvaluation=(claim:Claim)=>{
  if(evaluationResult?.claimId===claim.id)return evaluationResult;
  const policy=data.policies.find(p=>p.id===claim.policyId);const plan=policy&&data.plans.find(p=>p.id===policy.planId);
  const active=!!policy&&policy.status==='Active';
  const covered=!!plan&&plan.coveredTreatments.toLowerCase().includes(claim.treatment.toLowerCase().split(' ')[0]);
  const dateValid=!!policy&&claim.claimDate>=policy.startDate&&claim.claimDate<=policy.endDate;
  const limit=!!policy&&claim.amountINR<=policy.remainingLimitINR;
  const duplicate=data.claims.filter(c=>c.customerId===claim.customerId&&c.treatment.toLowerCase()===claim.treatment.toLowerCase()).length<2;
  const docs=claim.documents.length>0&&claim.documents.every(d=>d.status==='Verified');
  const checks=[['Policy validity',active],['Treatment coverage',covered],['Date validity',dateValid],['Remaining limits',limit],['Duplicate check',duplicate],['Documents verified',docs]];
  const failed=checks.filter(([,ok])=>!ok).length;
  const decision=failed===0?'APPROVE':failed===1?'MANUAL VERIFICATION':'REJECT';
  const risk=decision==='APPROVE'?'Low':decision==='MANUAL VERIFICATION'?'Medium':'High';
  const issues=checks.filter(([,ok])=>!ok).map(([label])=>String(label).toLowerCase());
  return {claimId:claim.id,checks,decision,risk,rationale:decision==='APPROVE'?'All eligibility checks pass.':`Review required: ${issues.join(', ')}.`};
 };
 const evaluateFromMySQL=async(claim:Claim)=>{try{const result=await apiJson(`/insurance/evaluate/${claim.id}`);const row=Array.isArray(result)&&result[0]?.[0]?result[0][0]:Array.isArray(result)&&result[0]?result[0]:result;const checks=[['Policy validity',row.policy_validity_check==='PASS'],['Treatment coverage',row.treatment_coverage_check==='PASS'],['Treatment date',row.treatment_date_check==='PASS'],['Coverage availability',row.coverage_check==='PASS'],['Duplicate check',row.duplicate_check==='PASS'],['Documents',row.document_check==='PASS']];const out={claimId:claim.id,checks,decision:String(row.recommended_decision||'').toUpperCase(),risk:row.risk_level,rationale:row.decision_explanation||'Decision returned by MySQL EvaluateClaim procedure.'};setEvaluationResult(out);setEvaluationRequested(true);return out}catch(e){notify(e instanceof Error?e.message:'MySQL evaluation failed',true);return null}};
