 const statCard=(label:string,value:string,note:string,Icon:any)=><div className="panel stat" key={label}><Icon size={16} color="#6F8436" style={{position:'absolute',right:17,top:15,zIndex:1}}/><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-note">{note}</div></div>;
 const status=(v:string)=><span className={`status ${v.toLowerCase().replace(/\s+/g,'-')}`}>{v}</span>;
