 const heading=(title:string,desc:string,action?:any)=><div className="page-head"><div><div className="eyebrow">ISIS · {canCompany?'Operations':'My cover'}</div><h1>{title}</h1><p className="page-description">{desc}</p></div>{action&&<div className="head-actions">{action}</div>}</div>;
